CREATE TRIGGER detached_copies_only_for_children_insert
BEFORE INSERT ON detached_copies
BEGIN
    SELECT RAISE(ABORT, 'Le copie messe da parte appartengono solo ai giochi dentro una collection')
    WHERE (SELECT parent_id FROM games WHERE id = NEW.game_id) IS NULL;
END;

CREATE TRIGGER detached_copies_only_for_children_update
BEFORE UPDATE ON detached_copies
BEGIN
    SELECT RAISE(ABORT, 'Le copie messe da parte appartengono solo ai giochi dentro una collection')
    WHERE (SELECT parent_id FROM games WHERE id = NEW.game_id) IS NULL;
END;

CREATE TRIGGER platforms_only_for_children_insert
BEFORE INSERT ON game_platforms
BEGIN
    SELECT RAISE(ABORT, 'La console di uscita si indica solo per i giochi dentro una collection')
    WHERE (SELECT parent_id FROM games WHERE id = NEW.game_id) IS NULL;
END;
